                an = emon.Port.CellsLen(a);
                emon.Port.CellsDrop(st, 0);
                emon.Port.CryptoAesEncrypt(emon.Port.CellsBytes(b), 0, 16, emon.Port.CellsBytes(a), 0, an, st);
                en = emon.Port.CellsLen(st);
                sum = 0;
                j = 0;
                while (j < 16) {
                    sum += emon.Port.CellsAt(st, j);
                    j += 1;
                }
                last = emon.Port.CellsAt(st, en - 1);
                CrHash((sum % 3) + 1, st, en, b);
                i += 1;
                if ((i >= 64) && (last <= (i - 32))) {
                    more = 0;
                }
            }
        }
        emon.Port.CellsDrop(b, 32);
        return 32;
    }
    internal static int CrTry56(emon.Port.Cells dc, int at, emon.Port.Src pw, int plen, int owner, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st) {
        // R5 and R6, algorithm 2.A: the owner password is checked against /O
        // with /U as extra data, the user password against /U; the file key is
        // /UE (or /OE) decrypted by AES-256-CBC, no padding, zero IV, under the
        // hash of the password and the key salt.
        int obase = at + CU;
        int ebase = at + CUe;
        int uat = 0;
        int ul = 0;
        int i = 0;
        int v = 0;
        if (owner == 1) {
            obase = at + CO;
            ebase = at + COe;
            uat = at + CU;
            ul = 48;
        }
        if (emon.Port.CellsAt(dc, at + CUlen) < 48) {
            return 0;
        }
        if (owner == 1) {
            if (emon.Port.CellsAt(dc, at + COlen) < 48) {
                return 0;
            }
        }
        CrHash56(dc, at, pw, plen, obase + 32, uat, ul, a, b, st);
        if (CrMatch(dc, obase, b, 32) == 0) {
            return 0;
        }
        CrHash56(dc, at, pw, plen, obase + 40, uat, ul, a, b, st);
        emon.Port.CellsDrop(a, 0);
        while (i < 16) {
            emon.Port.CellsPush(a, 0);
            i += 1;
        }
        CrCopy(dc, ebase, 32, a);
        emon.Port.CellsDrop(st, 0);
        emon.Port.CryptoAesDecrypt(emon.Port.CellsBytes(b), 0, 32, emon.Port.CellsBytes(a), 0, 48, 0, st);
        i = 0;
        while (i < 32) {
            v = emon.Port.CellsAt(st, i);
            emon.Port.CellsSet(dc, (at + CKey) + i, v);
            i += 1;
        }
        return 1;
    }
    internal static int CrTry(emon.Port.Cells dc, int at, emon.Port.Src pw, int plen, int owner, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st) {
        if (emon.Port.CellsAt(dc, at + CR) >= 5) {
            return CrTry56(dc, at, pw, plen, owner, a, b, st);
        }
        return CrTryLegacy(dc, at, pw, plen, owner, a, b, st);
    }
    internal static int CrResetSecrets(emon.Port.Cells dc, int at, int keepKey) {
        // What an attempt leaves behind is wiped: the padded password candidate (a
        // password, or the user password recovered from /O by the owner's) always;
        // the file key unless it was found (`keep-key` 1).
        int i = 0;
        while (i < 32) {
            if (keepKey == 0) {
                emon.Port.CellsSet(dc, (at + CKey) + i, 0);
            }
            emon.Port.CellsSet(dc, (at + CPad) + i, 0);
            i += 1;
        }
        return 0;
    }
    public static int CrAuthenticate(emon.Port.Cells dc, int at, emon.Port.Src pw, int plen, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st) {
        // Find the file key. Tried in order (D040): the empty USER password (a
        // document that opens for anyone), the supplied password as the user
        // password, the supplied password as the owner password, and the empty
        // owner password. `plen` is the length of the password held in `pw`; 0
        // means none supplied, and `pw` is then never read. Answers 1 and marks
        // the region active, or 0. The scratch cells are zeroed either way.
        int ok = 0;
        ok = CrTry(dc, at, pw, 0, 0, a, b, st);
        if ((ok == 0) && (plen > 0)) {
            ok = CrTry(dc, at, pw, plen, 0, a, b, st);
        }
        if ((ok == 0) && (plen > 0)) {
            ok = CrTry(dc, at, pw, plen, 1, a, b, st);
        }
        if (ok == 0) {
            ok = CrTry(dc, at, pw, 0, 1, a, b, st);
        }
        CrWipe(a);
        CrWipe(b);
        CrWipe(st);
        CrResetSecrets(dc, at, ok);
        if (ok == 1) {
            emon.Port.CellsSet(dc, at + CActive, 1);
        }
        return ok;
    }
    public static int CrObjectKey(emon.Port.Cells dc, int at, int mode, int num, int gen, emon.Port.Cells a, emon.Port.Cells b) {
        // Algorithm 1 (and 1.A): the key of object `num` `gen`, stored in the
        // region (`cr-okey-into` reads it back). RC4 and AES-128 hash the file key
        // with the low three bytes of the object number, the low two of the
        // generation and, for AES, the salt `sAlT`, and keep min(n + 5, 16) bytes;
        // AES-256 uses the file key itself. Answers the length; 0 for mode 0.
        emon.Port.CellsSet(dc, at + COklen, 0);
        if (mode == 0) {
            return 0;
        }
        int n = emon.Port.CellsAt(dc, at + CKlen);
        int an = 0;
        int kl = 0;
        int i = 0;
        int v = 0;
        if (mode == 3) {
            while (i < n) {
                v = emon.Port.CellsAt(dc, (at + CKey) + i);
                emon.Port.CellsSet(dc, (at + COkey) + i, v);
                i += 1;
            }
            emon.Port.CellsSet(dc, at + COklen, n);
            return n;
        }
        emon.Port.CellsDrop(a, 0);
        CrCopy(dc, at + CKey, n, a);
        emon.Port.CellsPush(a, num & 255);
        emon.Port.CellsPush(a, ((num) >> (8)) & 255);
        emon.Port.CellsPush(a, ((num) >> (16)) & 255);
        emon.Port.CellsPush(a, gen & 255);
        emon.Port.CellsPush(a, ((gen) >> (8)) & 255);
        if (mode == 2) {
            emon.Port.CellsPush(a, 115);
            emon.Port.CellsPush(a, 65);
            emon.Port.CellsPush(a, 108);
            emon.Port.CellsPush(a, 84);
        }
        an = emon.Port.CellsLen(a);
        CrHash(0, a, an, b);
        kl = n + 5;
        if (kl > 16) {
            kl = 16;
        }
        while (i < kl) {
            v = emon.Port.CellsAt(b, i);
            emon.Port.CellsSet(dc, (at + COkey) + i, v);
            i += 1;
        }
        emon.Port.CellsSet(dc, at + COklen, kl);
        CrWipe(a);
        CrWipe(b);
        return kl;
    }
    public static int CrOkeyInto(emon.Port.Cells dc, int at, emon.Port.Cells to) {
        // `to` (cleared) gets the object key `cr-object-key` stored. Answers its length.
        emon.Port.CellsDrop(to, 0);
        int n = emon.Port.CellsAt(dc, at + COklen);
        CrCopy(dc, at + COkey, n, to);
        return n;
    }
    public static int CrDecrypt(int mode, emon.Port.Cells key, int kn, byte[] data, int doff, int dlen, emon.Port.Cells @out) {
        // Decrypt data[doff, doff + dlen) under `key[0, kn)` into `out`, APPENDING:
        // RC4 for mode 1; for the AES modes the first 16 bytes are the IV and the
        // padding is removed. Answers how many bytes it appended (0 for mode 0,
        // which appends nothing: the caller keeps the data as it is).
        if (mode == 1) {
            return emon.Port.CryptoRc4(emon.Port.CellsBytes(key), 0, kn, data, doff, dlen, @out);
        }
        if (mode >= 2) {
            return emon.Port.CryptoAesDecrypt(emon.Port.CellsBytes(key), 0, kn, data, doff, dlen, 1, @out);
        }
        return 0;
    }
}
